"""Light ZH cast-name pollution sanitize for Opus post-MT.

Subset of Transub desktop ``mt-sanitize-core``: strip trailing / mid-cue
hallucinated names that are not justified by the (loop-cleaned) JA source.
External LLM paths keep the fuller desktop sanitize.
"""

from __future__ import annotations

import re

from ..asr_name_loops import is_name_only_debris, strip_asr_name_loops

# High-frequency Opus / soft-scene ZH cast tags (multi-char only for mid-strip).
_POLLUTION_MULTI: tuple[str, ...] = (
    "玲奈",
    "莉奈",
    "佳奈",
    "纱奈",
    "沙奈",
    "真理",
    "理子",
    "绘真",
    "绘里",
    "美咲",
    "结衣",
    "阳菜",
    "春奈",
    "桃子",
    "琴音",
    "黄奈",
    "奏翔",
    "斗碧",
    "乃爱",
    "爱奈",
    "露娜",
    "环奈",
    "花音",
    "雏子",
    "真寻",
    "圣音",
    "仓木",
    "北野",
)

_POLLUTION_SINGLE: frozenset[str] = frozenset(
    {"葵", "舞", "桃", "玲", "樱", "凛", "花", "月", "琉", "律", "春"}
)

_ZH_HONOR = r"(?:同学|小姐|先生|桑|君|酱|大人|老师)"
_KEEP_TRAILING = frozenset(
    {
        "好的",
        "是的",
        "不是",
        "没有",
        "可以",
        "不行",
        "没事",
        "对不起",
        "抱歉",
        "谢谢",
        "再见",
        "真的",
        "当然",
        "怎么",
        "什么",
        "哪里",
        "为什么",
        "好吧",
        "好啦",
        "嗯嗯",
        "啊啊",
        "哈哈",
    }
)
_KEEP_SINGLE = frozenset(
    {
        "嗯",
        "啊",
        "哦",
        "噢",
        "哈",
        "唔",
        "呃",
        "哼",
        "呀",
        "哟",
        "吧",
        "呢",
        "吗",
        "嘛",
        "啦",
        "哇",
        "唉",
        "诶",
        "欸",
        "啾",
        "咿",
        "呜",
        "呼",
        "呵",
        "嗨",
        "喂",
        "哎",
        "好",
    }
)

_TRAILING_RE = re.compile(
    rf"^(.*?)([\s。！？!?…，,；;：:])\s*"
    rf"([\u4e00-\u9fff]{{1,4}}{_ZH_HONOR}?|[A-Za-z][A-Za-z0-9'’\-]{{1,15}})$"
)
_HONOR_SUFFIX_RE = re.compile(rf"{_ZH_HONOR}$")


def _strip_honor(token: str) -> str:
    return _HONOR_SUFFIX_RE.sub("", str(token or "").strip())


def _source_justifies(stem: str, source_ja: str) -> bool:
    """
    Conservative justify: honorific / intro / literal after ASR loop strip.
    Name-only ASR debris does not justify.
    """
    stem = str(stem or "").strip()
    if not stem:
        return False
    raw = str(source_ja or "")
    cleaned, _ = strip_asr_name_loops(raw)
    if is_name_only_debris(cleaned):
        return False
    if stem in cleaned or stem in raw:
        # Require honorific / intro context for pollution stems, OR non-loop literal
        if any(f"{stem}{h}" in raw for h in ("さん", "くん", "ちゃん", "君", "様", "氏")):
            return True
        if re.search(
            rf"(?:私は|俺は|あたしは|僕は)?{re.escape(stem)}(?:です|だよ|だね)",
            raw,
        ):
            return True
        # Kanji name present outside loops (美咲と / 彼女の美咲)
        if stem in cleaned and not is_name_only_debris(cleaned):
            # Avoid particle false friends for single-char
            if len(stem) == 1:
                return bool(
                    re.search(rf"{re.escape(stem)}(?:さん|くん|ちゃん|君|様|氏)", raw)
                    or re.search(rf"(?:彼女の|彼の){re.escape(stem)}", raw)
                )
            return True
    # Hiragana/katakana readings commonly mapped by JA polish lexicon
    kana_map = {
        "美咲": ("みさき", "ミサキ"),
        "佳奈": ("かな",),  # honorific-only below
        "舞": ("マイ",),
        "桃子": ("ももこ", "モモコ"),
        "结衣": ("ゆい", "ユイ"),
        "真寻": ("まひろ", "マヒロ"),
        "玲奈": ("れいな", "レイナ"),
        "露娜": ("るな", "ルナ"),
        "阳菜": ("ひな", "ヒナ"),
        "花音": ("かのん", "カノン"),
    }
    for kana in kana_map.get(stem, ()):
        if any(f"{kana}{h}" in raw for h in ("さん", "くん", "ちゃん", "君", "様", "氏")):
            return True
        if kana in ("マイ",) and re.search(r"マイ(?![クペー])", raw):
            return True
        # Multi-char reading present in (loop-cleaned) source — not name-only debris
        if len(kana) >= 2 and kana in cleaned and not is_name_only_debris(cleaned):
            return True
    if stem == "佳奈":
        return False  # never trust bare かな
    return False


def _should_strip_trailing(token: str, head: str, source_ja: str) -> bool:
    t = str(token or "").strip()
    if not t or not head.strip():
        return False
    if t in _KEEP_TRAILING:
        return False
    if t in head:
        return False
    stem = _strip_honor(t)
    is_pollution = (
        stem in _POLLUTION_MULTI
        or t in _POLLUTION_MULTI
        or stem in _POLLUTION_SINGLE
        or t in _POLLUTION_SINGLE
    )
    justified = _source_justifies(stem, source_ja) or _source_justifies(t, source_ja)
    dialogue = len(re.sub(r"[\s。．.！？!?…，,、；;：:\-—·•~～'\"]+", "", head))
    short_intro = dialogue <= 4 and bool(re.search(r"[。．.]$", head.strip()))

    if justified:
        if is_pollution:
            if _HONOR_SUFFIX_RE.search(t):
                return True  # trailing 美咲桑 cast-tag
            if not short_intro:
                return True
            return False
        if short_intro:
            return False
        return True

    if is_pollution:
        return True
    if len(t) == 1 and re.fullmatch(r"[\u4e00-\u9fff]", t):
        if t in _KEEP_SINGLE:
            return False
        return True
    # Latin cast tags (Opus sometimes leaks romanized names)
    if re.fullmatch(r"[A-Za-z][A-Za-z0-9'’\-]{1,15}", t):
        return True
    # Do NOT strip arbitrary 2–4 Han (would delete 好舒服 / 过来 / dialogue).
    return False


def strip_trailing_cast_tags(zh: str, source_ja: str) -> str:
    cur = str(zh or "").rstrip()
    for _ in range(4):
        m = _TRAILING_RE.match(cur)
        if not m:
            break
        head = f"{m.group(1)}{m.group(2)}".rstrip()
        token = m.group(3)
        if not _should_strip_trailing(token, head, source_ja):
            break
        cur = head
    return cur


def strip_mid_pollution_names(zh: str, source_ja: str) -> str:
    cur = str(zh or "")
    stems = sorted(_POLLUTION_MULTI, key=lambda s: (-len(s), s))
    for stem in stems:
        if stem not in cur:
            continue
        if _source_justifies(stem, source_ja):
            # Collapse loops to a single stem
            esc = re.escape(stem)
            cur = re.sub(rf"(?:{esc}){{2,}}", stem, cur)
            cur = re.sub(
                rf"({esc})(?:\s*[…⋅・.。]{{1,6}}\s*(?:{esc}))+",
                r"\1",
                cur,
            )
            continue
        esc = re.escape(stem)
        cur = re.sub(rf"{esc}{_ZH_HONOR}?", "", cur)

    # Unjustified single-char: whole cue or … loops only
    for stem in _POLLUTION_SINGLE:
        if stem not in cur:
            continue
        if _source_justifies(stem, source_ja):
            continue
        esc = re.escape(stem)
        if re.fullmatch(rf"[\s…⋅・.。！？!?～〜\-]*{esc}[\s…⋅・.。！？!?～〜\-]*", cur.strip()):
            cur = ""
            continue
        cur = re.sub(rf"(?:{esc}){{2,}}", "", cur)
        cur = re.sub(rf"(?:{esc})(?:\s*[…⋅・.。]{{1,6}}\s*(?:{esc}))+", "", cur)

    cur = re.sub(r"[^\S\n]{2,}", " ", cur).strip()
    cur = re.sub(r"\s+([。．.！？!?…，,；;：:])", r"\1", cur)
    # Strip decorative ellipsis / wave debris only — keep sentence 。！？
    cur = re.sub(r"^[…⋅・～〜\s\-]+|[…⋅・～〜\s\-]+$", "", cur).strip()
    if re.fullmatch(r"[…⋅・.\s。！？!?～〜\-'\"，,]*", cur or ""):
        cur = ""
    return cur


def sanitize_zh_cast_pollution(source_ja: str, zh: str) -> str:
    """Opus post-MT: strip unjustified cast-name pollution."""
    out = str(zh or "").strip()
    if not out:
        return out
    out = strip_trailing_cast_tags(out, source_ja)
    out = strip_mid_pollution_names(out, source_ja)
    return out.strip()
